'use strict';
const $=s=>document.querySelector(s), app=$('#app'), cut=Date.parse(CONFIG.closesAt), demo=!CONFIG.endpoint;
const STORE=demo?'manunggal-demo-v3':'manunggal-live-v3', uuid=()=>crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');
const fresh=()=>({person:null,answers:Array.from({length:15},()=>[]),question:0,assessment:null,thinkingStart:null,wordStart:null,found:[],finalThree:null,wordEnd:null,page:1,readerHelp:false,wordUnlocked:false,queue:[],revision:0});
let state;try{state={...fresh(),...JSON.parse(localStorage.getItem(STORE)||(!demo&&localStorage.getItem('manunggal-live-v1'))||'{}')}}catch{state=fresh()}
const PREF_KEY='manunggal-display-preferences';
function readPrefs(){try{let p=JSON.parse(localStorage.getItem(PREF_KEY)||'{}');return {theme:['dark','light','system'].includes(p.theme)?p.theme:'dark',text:p.text==='large'?'large':'normal'}}catch{return {theme:'dark',text:'normal'}}}
let prefs=readPrefs();
function resolvedTheme(pref=prefs.theme,systemDark=typeof matchMedia==='function'&&matchMedia('(prefers-color-scheme: dark)').matches){return pref==='system'?(systemDark?'dark':'light'):pref==='light'?'light':'dark'}
function applyPrefs(){if(!document.body)return;document.body.dataset.theme=resolvedTheme();document.body.dataset.textSize=prefs.text;document.documentElement.style.colorScheme=resolvedTheme();let meta=document.querySelector('meta[name=theme-color]');if(meta)meta.content=resolvedTheme()==='dark'?'#101313':'#f5f1e8';let toggle=$('#appearance');if(toggle)toggle.setAttribute('aria-label','Pengaturan tampilan · '+prefs.theme)}
function setPrefs(changes){prefs={...prefs,...changes};try{localStorage.setItem(PREF_KEY,JSON.stringify(prefs))}catch{toast('Preferensi tidak dapat disimpan di perangkat.')}applyPrefs()}
let welcomePending=!!state.person,activeRoute='home',thinkingScreen='intro',readerScale=1,readerControls=true,readerBusy=false;
let storageError=false,clockOffset=0,serverChecked=false,serverClosed=false,closedAcked=false,syncing=false,retryAt=0,zoom=false,spread=true,toastTimer,selection=null,drag=null;
const now=()=>Date.now()+clockOffset, closed=()=>serverClosed||now()>=cut;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));storageError=false}catch{storageError=true}status()}
function status(){const el=$('#sync');if(!el)return;let msg=storageError?'Penyimpanan HP gagal':demo?'MODE UJI · lokal':closed()&&state.queue.length?'Tutup · data belum terkirim':state.queue.length?`Menunggu sinkron (${state.queue.length})`:serverChecked?'Data tersinkron':'Menghubungkan…';el.textContent=storageError||demo?msg:'';let profileEl=$('#profileSync');if(profileEl)profileEl.textContent=msg}
function toast(t){const e=$('#toast');e.textContent=t;e.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.style.display='none',2300)}
function enqueue(type,payload){if(demo)return;state.queue=state.queue.filter(e=>e.type!==type||e.person.id!==state.person.id);state.queue.push({id:uuid(),rev:++state.revision,type,person:{...state.person},payload});save();if(type==='assessment'||type==='word'&&payload.found.length===20)retryAt=0;scheduleSync()}
function jsonp(params){return new Promise((resolve,reject)=>{let cb='mg_'+uuid().replace(/-/g,''),s=document.createElement('script');let timer=setTimeout(()=>finish(null,new Error('timeout')),12000);function finish(v,e){clearTimeout(timer);delete window[cb];s.remove();e?reject(e):resolve(v)}window[cb]=v=>finish(v);s.onerror=()=>finish(null,new Error('network'));s.src=CONFIG.endpoint+'?'+new URLSearchParams({...params,callback:cb,t:Date.now()});document.head.append(s)})}
async function clock(){if(demo)return;try{let r=await jsonp({action:'status'});if(r.ok&&Number.isFinite(r.now)){clockOffset=r.now-Date.now();serverChecked=true;serverClosed=r.closed;status();if(closed()||app.querySelector('.closed'))render()}}catch{status()}}
function scheduleSync(){if(demo||syncing||Date.now()<retryAt||!navigator.onLine||!state.queue.length||(closed()&&closedAcked))return;setTimeout(sync,300+Math.random()*1800)}
async function sync(){if(syncing||demo||!state.queue.length||!navigator.onLine||Date.now()<retryAt)return;syncing=true;let batch=state.queue.slice(0,3);try{let ack=await jsonp({action:'ack',ids:batch.map(e=>e.id).join(',')});if(!ack.ok)throw Error('ack');const applyAck=r=>{let ids=new Set(r.received||[]);state.queue=state.queue.filter(e=>!ids.has(e.id));if(Number.isFinite(r.now)){clockOffset=r.now-Date.now();serverChecked=true;serverClosed=r.closed}save()};applyAck(ack);if(closed())closedAcked=true;batch=batch.filter(e=>state.queue.some(x=>x.id===e.id));if(batch.length&&!closed()){await fetch(CONFIG.endpoint,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=UTF-8'},body:JSON.stringify({events:batch}),redirect:'follow'});await new Promise(r=>setTimeout(r,1000));let r=await jsonp({action:'ack',ids:batch.map(e=>e.id).join(',')});if(!r.ok)throw Error('ack');applyAck(r);if(batch.some(e=>state.queue.some(x=>x.id===e.id)))throw Error('unconfirmed')}retryAt=Date.now()+20000}catch{retryAt=Date.now()+20000+Math.random()*20000}finally{syncing=false;status();if(closed()&&!app.querySelector('.closed'))render()}}
const types=[{code:'SK',name:'Sekuensial Konkret',en:'Concrete Sequential',color:'#326879',desc:'Anda cenderung menyukai fakta, keteraturan, langkah yang jelas, dan hasil yang dapat diperiksa.',strength:'Menjaga ketelitian, konsistensi, dan kepatuhan pada prosedur.',growth:'Berlatih menyesuaikan rencana saat keadaan berubah dan mencoba alternatif yang belum teruji.',team:'Menerjemahkan tujuan menjadi langkah yang terstruktur dan memastikan detail tidak terlewat.'},{code:'SA',name:'Sekuensial Abstrak',en:'Abstract Sequential',color:'#8264ae',desc:'Anda cenderung mengolah informasi melalui analisis, konsep, logika, dan pemikiran mendalam.',strength:'Menganalisis masalah, merancang strategi, dan menimbang alasan suatu keputusan.',growth:'Ubah gagasan menjadi langkah nyata dan beri ruang bagi kebutuhan sosial anggota tim.',team:'Membantu tim memahami alasan, pola, dan konsekuensi di balik keputusan.'},{code:'AA',name:'Acak Abstrak',en:'Abstract Random',color:'#458666',desc:'Anda cenderung menangkap makna, hubungan, intuisi, dan dinamika perasaan dalam suatu situasi.',strength:'Menghubungkan gagasan, memahami perspektif orang lain, serta membangun keterhubungan.',growth:'Periksa intuisi dengan fakta, perhatikan detail, dan kelola pengaruh suasana hati.',team:'Membantu tim memahami kebutuhan manusia dan menjaga kualitas hubungan.'},{code:'AK',name:'Acak Konkret',en:'Concrete Random',color:'#d18a32',desc:'Anda cenderung belajar melalui percobaan, pengalaman langsung, dan penemuan cara baru.',strength:'Beradaptasi, berinisiatif, mencoba solusi baru, dan bangkit dari kegagalan.',growth:'Tetapkan prioritas, batas waktu, dan cara mengevaluasi hasil percobaan.',team:'Mendorong tim berani mencoba, bergerak, dan menyesuaikan pendekatan.'}];
