function score(answers){if(answers.length!==15||answers.some(a=>a.length!==2||new Set(a).size!==2||a.some(x=>!Number.isInteger(x)||x<0||x>3)))throw Error('Jawaban belum lengkap');let v=[0,0,0,0];answers.forEach((a,i)=>a.forEach(x=>v[DATA.key[i].indexOf('ABCD'[x])]++));return v}
function profile(v){let max=Math.max(...v),ix=v.map((s,i)=>({s,i})).filter(x=>max-x.s<=1).map(x=>x.i),id=ix.map(i=>types[i].code).join('+'),lead=v.map((s,i)=>s===max?types[i].code:null).filter(Boolean).join(' + ');let t=types[ix[0]],copy=ix.length===1?[t.desc,t.strength,t.growth,t.team]:blends[id];return {ix,id,lead,label:['','Single Preference','Dual Preference','Triple Preference','Balanced Preference'][ix.length],copy}}
function route(){return location.hash.slice(1)||'home'}function go(r){if(route()===r)render();else requestRoute(r)}function nav(t){return `<div class="navline"><a class="back-big" href="#home">← Kembali</a><span class="eyebrow" style="margin:0">${t}</span></div>`}function name(){return esc(state.person?.name||'')}
function render(){selection=null;drag=null;status();shell();if(closed()){closeDialog();app.innerHTML=`<section class="closed"><p class="eyebrow">MANUNGGAL · EXPERIENCE COMPLETED</p><h1>The journey ends here.</h1><h2><i>The purpose continues.</i></h2><p>Terima kasih telah bergerak bersama. Perjalanan hari ini telah selesai.</p>${state.queue.length?'<p class="notice">Ada data yang belum dikonfirmasi server. Hubungi fasilitator MOTU.</p>':''}<p class="quote">Sesarengan Dados Setunggal</p></section>`;return}if(!state.person){registration();return}if(welcomePending){welcomeBack();return}switch(route()){case'magazine':magazine();break;case'thinking':thinkingIntro();break;case'word':word();break;case'profile':participantProfile();break;default:home()}}
function registration(){app.innerHTML=`${demo?'<div class="demo">MODE UJI · Data hanya tersimpan pada perangkat ini.</div>':''}<div class="hero"><div class="copy"><p class="eyebrow">04 Desember 2026 · National Sales Meeting</p><h1>Manunggal.</h1><p class="tag">Sesarengan Dados Setunggal</p><p>Different Minds, Shared Purpose.</p></div><img src="assets/hero.webp" alt="Tangan membuka peta perjalanan Borobudur"></div><form id="registration" class="panel narrow"><p class="eyebrow">Begin your journey</p><h2>Mari berkenalan.</h2><label class="field">Nama lengkap<input required maxlength="100" name="name" autocomplete="name" placeholder="Nama Anda"></label><label class="field">Nomor tim<select required name="team"><option value="">Pilih tim</option>${Array.from({length:30},(_,i)=>`<option value="${i+1}">Tim ${String(i+1).padStart(2,'0')}</option>`).join('')}</select></label><label class="consent"><input required type="checkbox" name="consent"><span>Saya memahami bahwa nama, nomor tim, jawaban, hasil Thinking Style, dan progres Word Hunt digunakan MOTU untuk pembelajaran dan evaluasi kegiatan. Hasil bukan penilaian kompetensi; akses data individual dibatasi kepada pengelola MOTU.</span></label><button class="btn full">Begin Your Journey →</button><p class="small" style="margin-top:12px">Gunakan satu perangkat untuk melanjutkan progres. Hubungi fasilitator untuk pertanyaan tentang data.</p></form>`;$('#registration').onsubmit=e=>{e.preventDefault();if(closed())return render();let f=new FormData(e.target),n=f.get('name').trim();if(!n||/[\x00-\x1f\x7f]/.test(n))return toast('Isi nama yang valid.');state.person={id:uuid(),name:n,team:Number(f.get('team')),consent:true};welcomePending=false;save();enqueue('register',{});go('home')}}
const ICONS={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',magazine:'<path d="M12 7c-3-3-6-3-9-2v14c3-1 6-1 9 2 3-3 6-3 9-2V5c-3-1-6-1-9 2v14"/>',thinking:'<path d="M12 4a3 3 0 0 0-5-2 4 4 0 0 0-3 5 4 4 0 0 0-1 7 4 4 0 0 0 4 6 3 3 0 0 0 5-2V4Zm0 0a3 3 0 0 1 5-2 4 4 0 0 1 3 5 4 4 0 0 1 1 7 4 4 0 0 1-4 6 3 3 0 0 1-5-2M7 7c0 2 1 3 3 3M5 15c2 0 3-1 3-3m9-5c0 2-1 3-3 3m5 5c-2 0-3-1-3-3"/>',word:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 3v18M15 3v18M3 9h18M3 15h18"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>',check:'<path d="m5 12 4 4L19 6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>'};
function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" class="ui-icon">${ICONS[n]||''}</svg>`}
function shell(){let r=route(),active=!!state.person&&!closed();if(document.body){applyPrefs();document.body.dataset.route=active?r:closed()?'closed':'registration'}let b=$('#bottomNav');if(!b)return;b.hidden=!active||r==='magazine'||welcomePending;b.innerHTML=active?[["home","Home"],["magazine","Guide"],["thinking","Discover"],["word","Challenge"]].map(([key,label])=>`<a href="#${key}" ${key===r?'aria-current="page"':''}>${icon(key)}<span>${label}</span>${key==='word'&&!state.wordUnlocked?'<i class="nav-dot"></i>':''}</a>`).join(''):''}
function home(){let done=state.answers.filter(a=>a.length===2).length;let cards=[['magazine','Experience Guide','Digital Magazine',state.page>1?'Halaman '+state.page+' / 14':'Buka majalah'],['thinking','Thinking Style','Self Discovery',state.assessment?'Lihat hasil ✓':state.thinkingStart?done+' / 15 dijawab':'Mulai assessment'],['word','Word Hunt','The Challenge',!state.wordUnlocked?'Terkunci':state.wordEnd?'Selesai ✓':state.wordStart?(state.found.length>=10?state.found.length+' / 20':state.found.length+' kata'):'Siap dimulai']];app.innerHTML=`<div class="home-heading"><p class="eyebrow">NATIONAL SALES MEETING · 04 DESEMBER 2026</p><h1>Manunggal<span>.</span></h1><p class="tag">Different Minds, Shared Purpose.</p></div><figure class="home-photo"><img src="assets/hero.webp" alt="Tangan membuka peta perjalanan Borobudur"></figure><div class="welcome"><div><p class="welcome-name">Selamat datang, ${name()}.</p><p class="small">Perjalanan kita dimulai di sini.</p></div><span class="team-chip">TIM ${String(state.person.team).padStart(2,'0')}</span></div><div class="row spread section-label"><p class="eyebrow">YOUR EXPERIENCE</p><span class="small">01 — 03</span></div><div class="app-modules">${cards.map(([key,title,sub,progress])=>`<a class="app-tile" href="#${key}">${icon(key)}<strong>${title}</strong><small>${sub}</small><span class="tile-status ${key==='word'&&!state.wordUnlocked?'locked':''}">${key==='word'&&!state.wordUnlocked?icon('lock'):''}${progress}</span></a>`).join('')}</div><div class="home-meta"><button id="openProfile" class="profile-link">${icon('user')} Profil peserta</button></div><p class="credit">An experience designed by <b>MOTU Consulting</b></p>`;$('#openProfile').onclick=()=>go('profile')}
function thinkingIntro(){thinkingScreen='intro';app.innerHTML=nav('02 / Discover')+`<article class="panel narrow intro"><div class="intro-banner">${icon('thinking')}<p class="eyebrow">MANUNGGAL / SELF DISCOVERY</p><h2>Discover How You Think.</h2><p class="tag">Understanding yourself is the beginning of understanding others.</p></div><h2>Inventori Gaya Berpikir</h2><p>Setiap orang memiliki cara yang berbeda dalam memahami informasi, melihat suatu situasi, mengambil keputusan, dan menyelesaikan permasalahan.</p><p>Perbedaan tersebut bukan tentang siapa yang lebih baik, melainkan tentang bagaimana setiap individu memiliki kecenderungan dan kekuatannya masing-masing.</p><p>Melalui inventori sederhana ini, Anda diajak mengenali preferensi gaya berpikir yang paling sering Anda gunakan dalam kehidupan sehari-hari.</p><div class="profile-section"><h3>Petunjuk pengisian</h3><ol class="instructions"><li>Bacalah setiap pilihan (A, B, C, D) dengan saksama.</li><li>Pilih <b>dua dari empat pilihan</b> yang paling menggambarkan diri Anda.</li><li>Pilih berdasarkan kecenderungan Anda yang sebenarnya, bukan berdasarkan apa yang menurut Anda seharusnya menjadi diri Anda.</li><li>Tidak ada jawaban benar atau salah. Setiap pilihan sama pentingnya.</li><li>Jawablah secara mandiri dan alami, tanpa terlalu lama mempertimbangkan setiap pilihan.</li></ol></div><div class="intro-facts"><div><b>15</b><span>Kelompok pernyataan</span></div><div><b>5–7</b><span>Menit (perkiraan)</span></div></div><p class="notice">Hasil inventori merupakan bahan refleksi, bukan diagnosis psikologis, ukuran kecerdasan, atau penilaian kompetensi.</p><button id="startThinking" class="btn full">${state.assessment?'Lihat Hasil Saya':state.thinkingStart?'Lanjutkan Assessment':'Start My Discovery'} ${icon('arrow')}</button></article>`;$('#startThinking').onclick=()=>{if(closed())return render();if(state.assessment)return result();state.thinkingStart=state.thinkingStart||now();save();thinking();scrollTo(0,0)}}
function validAccess(value){return String(value).trim()==='MOTU'}
function wordGate(){app.innerHTML=nav('03 / Challenge')+`<section class="gate narrow"><div class="gate-icon">${icon('lock')}</div><p class="eyebrow">THE CHALLENGE</p><h2>Beyond What We See.</h2><p class="tag">Some discoveries have their own moment.</p><p>Tantangan ini belum dimulai. Fasilitator akan memberikan kode akses ketika waktunya tiba.</p><form id="unlockForm" class="gate-form"><label class="field">Access Code<input id="accessCode" name="code" type="password" placeholder="Masukkan kode akses" autocomplete="off" autocapitalize="characters" required maxlength="32"></label><p id="accessError" class="error" role="alert" hidden>Kode akses belum tepat. Silakan coba kembali.</p><button class="btn gold full">Unlock the Challenge ${icon('arrow')}</button></form><p class="small">The discovery awaits.</p></section>`;$('#unlockForm').onsubmit=e=>{e.preventDefault();if(closed())return render();if(!validAccess($('#accessCode').value)){ $('#accessError').hidden=false;return}state.wordUnlocked=true;save();shell();word();scrollTo(0,0)}}
function wordIntro(){app.innerHTML=nav('03 / Challenge')+`<section class="gate narrow"><div class="gate-icon">${icon('word')}</div><p class="eyebrow">WORD HUNT</p><h2>Beyond What We See.</h2><p class="tag">There is always more than meets the eye.</p><p>Di balik susunan huruf ini, terdapat sejumlah kata yang menunggu untuk ditemukan.</p><div class="word-instructions"><h3>Petunjuk tantangan</h3><p>Temukan kata-kata tersembunyi dalam bahasa Indonesia dan bahasa Inggris. Kata dapat tersusun secara horizontal, vertikal, maupun diagonal, termasuk arah terbalik.</p><p>Geser jari sepanjang kata, atau ketuk huruf awal dan huruf akhir. Kamu dapat berdiskusi dengan anggota tim.</p><p>Amati dengan saksama. Jelajahi setiap kemungkinan.</p></div><button id="startWord" class="btn gold full">Mulai Tantangan ${icon('arrow')}</button></section>`;$('#startWord').onclick=()=>{if(closed())return render();state.wordStart=now();save();sendWord();word();scrollTo(0,0)}}
const pageTitles=['Sampul depan','Different Individuals, Shared Direction','Every Journey Begins Somewhere','How to Experience This Journey','Blind Tower','Secret Code','Magic Rope','Puzzle Project','Painting Project','Water Transfer','Photo Hunt','E.T.I.L','The Purpose Continues','Sampul belakang'];
function tocMarkup(p,p2){return '<div class="contents-list">'+pageTitles.map((t,i)=>{let n=i+1,station=n>=5&&n<=12?'Pos '+String(n-4).padStart(2,'0')+' · Tantangan':'Experience Guide';return `<button class="contents-item ${n===p||n===p2?'current':''}" data-jump="${n}" ${n===p||n===p2?'aria-current="page"':''}><span class="toc-num">${String(n).padStart(2,'0')}</span><span class="toc-label"><small>${station}</small><strong>${t}</strong></span><span aria-hidden="true">${n===p||n===p2?'✓':'›'}</span></button>`}).join('')+'</div>'}
const pageImg=n=>`<img draggable="false" src="assets/pages/${String(n).padStart(2,'0')}.webp" alt="Halaman ${n}: ${pageTitles[n-1]}">`;
function spreadEnabled(){return spread&&innerWidth>=620&&innerWidth>innerHeight}
function readerPage(n){return spreadEnabled()&&n>1&&n<14&&n%2?n-1:n}
function pageStep(p,d){if(!spreadEnabled())return p+d;if(d>0)return p===1?2:p===14?14:p+2;return p===14?12:p===2?1:p-2}
function readerHelp(){showDialog('Enjoy Your Reading','<div class="reader-guide"><span>←<small>Ketuk kiri</small></span><span>→<small>Ketuk kanan</small></span></div><p>Geser ke kiri untuk lanjut, ke kanan untuk kembali. Ketuk bagian tengah untuk menyembunyikan atau menampilkan kontrol. Cubit dengan dua jari atau ketuk dua kali untuk memperbesar.</p>', 'Mulai Membaca',null,()=>{state.readerHelp=true;save()})}
function magazine(){let p=readerPage(state.page||1),dual=spreadEnabled()&&p>1&&p<14,p2=dual?p+1:null;state.page=p;readerBusy=false;app.innerHTML=`<section class="book-reader ${readerControls?'':'controls-hidden'}" id="bookReader"><header class="book-top"><a class="back-big" href="#home">← Kembali</a><span>Experience Guide</span><button id="contents" aria-label="Daftar isi">☰</button></header><div class="book-stage" id="bookStage"><div class="book-sheet ${dual?'double':''}" id="pages"><div class="page-base">${pageImg(p)}${p2?pageImg(p2):''}</div></div></div><div class="book-bottom"><div class="reader-actions"><button id="prev" aria-label="Halaman sebelumnya" ${p<=1?'disabled':''}>‹</button><span id="pageCount">${p}${p2?'–'+p2:''} / 14</span><button id="next" aria-label="Halaman selanjutnya" ${p>=14?'disabled':''}>›</button><button id="zoom" aria-label="Perbesar halaman">＋</button><button id="spread" aria-label="Ubah mode halaman" ${innerWidth<620||innerWidth<=innerHeight?'disabled':''}>${spreadEnabled()?'1':'2'} hlm</button><button id="helpReader" aria-label="Petunjuk membaca">?</button></div><button id="contentsBottom" class="toc-trigger" aria-label="Buka daftar isi"><span aria-hidden="true">☰</span> Daftar Isi <span class="toc-current">${p>=5&&p<=12?'Pos '+String(p-4).padStart(2,'0')+' · ':''}${pageTitles[p-1]}${p2?' / '+pageTitles[p2-1]:''}</span><span aria-hidden="true">⌃</span></button><p>Ketuk kiri / kanan atau geser untuk membalik halaman</p></div></section>`;
let stage=$('#bookStage'),sheet=$('#pages'),book=$('#bookReader'),panX=0,panY=0,points=new Map(),gesture=null,lastTap=0,lastX=0,lastY=0,tapTimer=null;
function applyZoom(){sheet.style.transform=`translate(${panX}px,${panY}px) scale(${readerScale})`;stage.classList.toggle('is-zoomed',readerScale>1);$('#zoom').textContent=readerScale>1?'−':'＋'}
function scaleTo(v){readerScale=Math.max(1,Math.min(3,v));if(readerScale===1){panX=panY=0}else{let maxX=sheet.offsetWidth*(readerScale-1)/2,maxY=sheet.offsetHeight*(readerScale-1)/2;panX=Math.max(-maxX,Math.min(maxX,panX));panY=Math.max(-maxY,Math.min(maxY,panY))}applyZoom()}
function toggleControls(){readerControls=!readerControls;book.classList.toggle('controls-hidden',!readerControls)}
function change(n,animated=true){n=readerPage(Math.max(1,Math.min(14,n)));if(n===p||readerBusy)return;clearTimeout(tapTimer);readerScale=1;panX=panY=0;applyZoom();state.page=n;save();let nd=spreadEnabled()&&n>1&&n<14,d=n>p?1:-1;if(!animated||matchMedia('(prefers-reduced-motion: reduce)').matches){magazine();return}readerBusy=true;let leaf=document.createElement('div');leaf.className=`turn-leaf ${d>0?'forward':'backward'} ${dual&&nd?'half':'whole'}`;let front=dual&&d>0?p2:p,back=dual&&nd?(d>0?n:n+1):n;
if(dual&&nd){sheet.querySelector('.page-base').innerHTML=d>0?pageImg(p)+pageImg(n+1):pageImg(n)+pageImg(p2)}else{sheet.querySelector('.page-base').innerHTML=pageImg(n);sheet.querySelector('.page-base').classList.add('single-transition')}
leaf.innerHTML=`<div class="leaf-face front">${pageImg(front)}</div><div class="leaf-face rear">${pageImg(back)}</div>`;sheet.append(leaf);let complete=()=>{if(route()==='magazine'&&!closed()&&book.isConnected){readerBusy=false;magazine()}};leaf.addEventListener('animationend',complete,{once:true});setTimeout(complete,780)}
$('#prev').onclick=()=>change(pageStep(p,-1));$('#next').onclick=()=>change(pageStep(p,1));$('#zoom').onclick=()=>scaleTo(readerScale>1?1:2);$('#spread').onclick=()=>{spread=!spread;readerScale=1;magazine()};$('#helpReader').onclick=readerHelp;function openContents(){showDialog('Daftar Isi','<p class="toc-intro">Pilih halaman atau tantangan yang ingin Anda buka.</p>'+tocMarkup(p,p2),'Tutup',null);let dlg=$('#appDialog');dlg.classList.add('bottom-sheet');document.querySelectorAll('[data-jump]').forEach(el=>el.onclick=()=>{closeDialog();change(+el.dataset.jump,false)});let current=dlg.querySelector('.contents-item.current');if(current)current.scrollIntoView({block:'nearest'})}$('#contents').onclick=openContents;$('#contentsBottom').onclick=openContents;
function distance(){let a=[...points.values()];return Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)}
stage.onpointerdown=e=>{if(readerBusy||e.button!==0)return;stage.setPointerCapture(e.pointerId);points.set(e.pointerId,{x:e.clientX,y:e.clientY});if(points.size===1)gesture={x:e.clientX,y:e.clientY,panX,panY,kind:'single'};if(points.size===2){clearTimeout(tapTimer);gesture={kind:'pinch',distance:distance(),scale:readerScale}}};stage.onpointermove=e=>{if(!points.has(e.pointerId)||!gesture)return;points.set(e.pointerId,{x:e.clientX,y:e.clientY});if(points.size===2&&gesture.kind==='pinch')scaleTo(gesture.scale*distance()/Math.max(1,gesture.distance));else if(points.size===1&&gesture.kind==='single'&&readerScale>1){panX=gesture.panX+e.clientX-gesture.x;panY=gesture.panY+e.clientY-gesture.y;scaleTo(readerScale)}};stage.onpointerup=e=>{if(!points.has(e.pointerId))return;points.delete(e.pointerId);let g=gesture;if(points.size){gesture={kind:'pinch'};return}gesture=null;if(!g||g.kind!=='single')return;let dx=e.clientX-g.x,dy=e.clientY-g.y;if(Math.hypot(dx,dy)>40){if(readerScale===1&&Math.abs(dx)>Math.abs(dy)*1.15)change(pageStep(p,dx<0?1:-1));return}if(Math.hypot(dx,dy)>12)return;let t=Date.now();if(t-lastTap<320&&Math.hypot(e.clientX-lastX,e.clientY-lastY)<45){clearTimeout(tapTimer);lastTap=0;scaleTo(readerScale>1?1:2);return}lastTap=t;lastX=e.clientX;lastY=e.clientY;tapTimer=setTimeout(()=>{if(!book.isConnected)return;let bounds=stage.getBoundingClientRect(),rel=(e.clientX-bounds.left)/bounds.width;if(readerScale>1||rel>=.30&&rel<=.70)toggleControls();else change(pageStep(p,rel>.70?1:-1))},330)};stage.onpointercancel=()=>{points.clear();gesture=null};
applyZoom();for(let i of [p-1,p+1,p+2,p+3])if(i>=1&&i<=14){let img=new Image();img.src=`assets/pages/${String(i).padStart(2,'0')}.webp`}if(!state.readerHelp)readerHelp();}

function thinking(){thinkingScreen='questions';if(state.assessment)return result();if(!state.thinkingStart)return thinkingIntro();let q=state.question,a=state.answers[q];app.innerHTML=nav('02 / Discover')+`<section class="panel narrow question-panel"><div class="row spread"><p class="eyebrow">Thinking Style Assessment</p><span class="small">${q+1} / 15</span></div><div class="progress"><i style="width:${(q+1)/15*100}%"></i></div><h2>Manakah yang paling menggambarkan diri Anda?</h2><p>Pilih tepat dua karakteristik yang paling sesuai dengan diri Anda. Tidak ada jawaban benar atau salah.</p><div class="choices">${DATA.questions[q].map((t,i)=>`<button class="choice" data-choice="${i}" aria-pressed="${a.includes(i)}"><b>${'ABCD'[i]}</b>${esc(t)}</button>`).join('')}</div><div class="row spread"><span class="small" id="choiceCount">${a.length} dari 2 pilihan</span><span class="small">Jawab sesuai diri Anda saat ini.</span></div><div class="row spread" style="margin-top:18px"><button id="backQ" class="btn secondary" ${q===0?'disabled':''}>← Sebelumnya</button><button id="nextQ" class="btn" ${a.length!==2?'disabled':''}>${q===14?'Lihat hasil':'Selanjutnya'} →</button></div></section>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{let i=+b.dataset.choice;if(a.includes(i))a.splice(a.indexOf(i),1);else if(a.length<2)a.push(i);else return toast('Pilih dua saja. Batalkan salah satu pilihan.');save();document.querySelectorAll('[data-choice]').forEach(el=>el.setAttribute('aria-pressed',String(a.includes(+el.dataset.choice))));$('#choiceCount').textContent=a.length+' dari 2 pilihan';$('#nextQ').disabled=a.length!==2});$('#backQ').onclick=()=>{state.question--;save();thinking()};$('#nextQ').onclick=()=>{if(closed())return render();if(a.length!==2)return;if(q<14){state.question++;save();thinking();scrollTo(0,0)}else{try{let v=score(state.answers);state.assessment={scores:v,started:state.thinkingStart,ended:now()};save();enqueue('assessment',{answers:state.answers.map(a=>a.slice()),started:state.assessment.started,ended:state.assessment.ended});result();scrollTo(0,0)}catch{toast('Periksa kembali seluruh jawaban.')}}}}
function result(){thinkingScreen='result';let v=state.assessment.scores,p=profile(v),copy=p.copy;app.innerHTML=nav('02 / Discover')+`<article class="panel narrow"><div class="profileHead"><p class="eyebrow">Your personal thinking profile</p><h2>${p.id.replaceAll('+',' + ')}</h2><p>${p.label} · ${name()}</p><p>${p.ix.map(i=>types[i].name).join(' · ')}</p><small style="color:#e5ca96">Skor tertinggi: ${p.lead}</small></div><h3>Four ways of thinking</h3><div class="bars">${types.map((t,i)=>`<div><div class="row spread"><span>${t.name} (${t.code})</span><b>${v[i]}/15</b></div><div class="bar"><i style="width:${v[i]/15*100}%;background:${t.color}"></i></div></div>`).join('')}</div><p class="small">Total 30 poin. Skor tertinggi dan skor dalam selisih satu poin dikelompokkan sebagai preferensi yang menonjol. Empat skor dalam rentang satu poin disebut relatif seimbang.</p>${['Understanding Your Mind','Your Potential Strengths','Your Growth Opportunities','Your Contribution to the Team'].map((h,i)=>`<section class="profile-section"><h3>${h}</h3><p>${copy[i]}</p></section>`).join('')}<section class="profile-section"><h3>Explore all four styles</h3>${types.map(t=>`<details style="padding:10px 0;border-bottom:1px solid var(--line)"><summary><b>${t.code} · ${t.name}</b></summary><p>${t.desc}</p><p><b>Potensi:</b> ${t.strength}</p><p><b>Pengembangan:</b> ${t.growth}</p></details>`).join('')}</section><p class="quote">We don't need to think alike to move together.</p><p>Bagaimana Anda dapat memanfaatkan cara berpikir Anda sekaligus memberi ruang bagi cara berpikir orang lain?</p><p class="small">Hasil merupakan bahan refleksi diri, bukan diagnosis psikologis, ukuran kecerdasan atau penilaian kompetensi. Batas satu poin merupakan aturan interpretasi kegiatan, bukan ambang psikometrik tervalidasi.</p><button class="btn full" id="saveProfile">Simpan profil sebagai gambar ↓</button><button class="link" id="readIntro">Baca kembali petunjuk</button></article>`;$('#saveProfile').onclick=()=>saveCard(v,p);$('#readIntro').onclick=()=>{thinkingIntro();scrollTo(0,0)}}
function saveCard(v,p){let c=document.createElement('canvas');c.width=1080;c.height=1450;let x=c.getContext('2d');x.fillStyle='#f6f2e9';x.fillRect(0,0,1080,1450);x.fillStyle='#123a44';x.fillRect(0,0,1080,390);x.fillStyle='#e7c789';x.font='bold 25px sans-serif';x.fillText('MANUNGGAL / YOUR THINKING PROFILE',65,70);x.fillStyle='white';x.font='bold 70px Georgia';x.fillText(p.id.replaceAll('+',' + '),65,170);x.font='34px sans-serif';x.fillText(p.label,65,230);x.font='28px sans-serif';x.fillText(state.person.name.slice(0,48),65,290);x.fillText('Tim '+state.person.team,65,335);types.forEach((t,i)=>{let y=455+i*100;x.fillStyle='#123a44';x.font='bold 28px sans-serif';x.fillText(t.name,65,y);x.fillText(v[i]+'/15',920,y);x.fillStyle='#ded6c9';x.fillRect(65,y+20,950,19);x.fillStyle=t.color;x.fillRect(65,y+20,950*v[i]/15,19)});function wrap(text,y){x.fillStyle='#123a44';x.font='29px sans-serif';let l='';for(let w of text.split(' ')){if(x.measureText(l+w).width>940){x.fillText(l,65,y);y+=39;l=''}l+=w+' '}if(l)x.fillText(l,65,y);return y+45}let y=wrap(p.copy[0],900);y=wrap(p.copy[3],y+18);x.font='italic 31px Georgia';x.fillText('Different Minds, Shared Purpose.',65,1330);x.font='22px sans-serif';x.fillText('Bahan refleksi diri · bukan penilaian kompetensi',65,1380);c.toBlob(async blob=>{if(!blob)return;let file=new File([blob],'Manunggal-Thinking-Profile.png',{type:'image/png'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Your Thinking Profile'});return}}catch(e){if(e.name==='AbortError')return}let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)},'image/png')}
function word(){if(!state.wordUnlocked)return wordGate();if(!state.wordStart)return wordIntro();let n=state.found.length,finished=n===20;app.innerHTML=nav('03 / Challenge')+`<section class="game"><div class="panel"><p class="eyebrow">Word Hunt · Beyond What We See</p><div class="gameHeader"><h2>${finished?'Discovery complete.':n>=17?'Almost there.':n>=10?"Go beyond.":'What can you find?'}</h2><div class="gameCount" aria-label="Jumlah kata ditemukan">${n}${n>=10?' / 20':''}</div></div><p class="small">Kata ditemukan</p>${n>=10?`<div class="progress"><i style="width:${n*5}%"></i></div>`:''}${n<10?'<p class="small">Temukan kata Indonesia dan Inggris dalam berbagai arah.</p>':n===10?'<div class="notice"><b>You’re halfway there!</b><br>Sepuluh kata telah ditemukan. Ternyata masih ada sepuluh kata lainnya yang menunggu untuk ditemukan.</div>':n>=17&&!finished?'<div class="notice"><b>The Final Three</b><br>Kenali makna tiga kata terakhir untuk menyelesaikan perjalananmu.</div>':''}${finished?'<div class="notice"><b>More than just words.</b><br>Seluruh kata telah ditemukan. Kata-kata ini mendapatkan makna ketika diwujudkan dalam cara kita berpikir, bertindak, dan bekerja bersama.</div>':''}<p class="small">Geser jari sepanjang kata, atau ketuk huruf awal lalu huruf akhir. Kata lain di luar daftar misi tidak dihitung.</p><div class="board" id="board" role="group" aria-label="Papan huruf 16 kali 16">${DATA.board.map((line,r)=>Array.from(line,(ch,c)=>`<span class="cell" data-cell="${r*16+c}" role="button" tabindex="${r===0&&c===0?'0':'-1'}" aria-label="Baris ${r+1}, kolom ${c+1}, huruf ${ch}">${ch}</span>`).join('')).join('')}</div>${state.finalThree?`<section style="margin-top:16px"><p class="eyebrow">The final three · Definisi</p>${state.finalThree.map((w,i)=>`<div class="clue ${state.found.includes(w)?'done':''}">${i+1}. ${esc(DATA.words[w])} ${state.found.includes(w)?`<b>✓ ${w}</b>`:''}</div>`).join('')}</section>`:''}<details class="profile-section discoveries" ${finished?'open':''}><summary>Your discoveries · ${n} kata</summary><div class="wordlist">${state.found.map(w=>`<span>${w}</span>`).join('')||'<small>Kata yang ditemukan akan muncul di sini.</small>'}</div></details>${finished?'<p class="quote">TRUST · ACCOUNTABILITY · COMMITMENT · OWNERSHIP</p><a class="btn full" href="#home">Kembali ke Experience Hub</a>':''}</div><p class="small">Progres disimpan otomatis. Diskusikan penemuan bersama tim.</p></section>`;paint();if(!finished)wireBoard()}
const idx=(r,c)=>r*16+c;
function path(a,b){if(a==null||b==null)return[];let r=Math.floor(a/16),c=a%16,er=Math.floor(b/16),ec=b%16,dr=er-r,dc=ec-c;if(dr&&dc&&Math.abs(dr)!==Math.abs(dc))return[];let n=Math.max(Math.abs(dr),Math.abs(dc));return Array.from({length:n+1},(_,i)=>idx(r+Math.sign(dr)*i,c+Math.sign(dc)*i))}
function paint(active=[]){const found=new Set(state.found.flatMap(w=>DATA.paths[w].map(([r,c])=>idx(r,c))));document.querySelectorAll('.cell').forEach(el=>{let n=+el.dataset.cell;el.classList.toggle('found',found.has(n));el.classList.toggle('active',active.includes(n));el.classList.toggle('start',selection===n)})}
function sendWord(){enqueue('word',{found:state.found.slice(),started:state.wordStart,ended:state.wordEnd})}
function choose(a,b){if(closed())return render();if(!state.wordUnlocked||!state.wordStart)return word();let p=path(a,b);selection=null;drag=null;if(p.length<2){paint();return}let text=p.map(n=>DATA.board[Math.floor(n/16)][n%16]).join(''),rev=Array.from(text).reverse().join(''),w=Object.hasOwn(DATA.words,text)?text:Object.hasOwn(DATA.words,rev)?rev:null;if(!w){paint();return toast('Belum termasuk kata yang tersembunyi. Coba lagi.')}if(state.found.includes(w)){paint();return toast('Kata ini sudah ditemukan.')}state.found.push(w);let n=state.found.length;if(n===17)state.finalThree=Object.keys(DATA.words).filter(x=>!state.found.includes(x));if(n===20)state.wordEnd=now();save();sendWord();let sy=scrollY;word();scrollTo(0,sy);if(n===10||n===17){let notice=app.querySelector('.notice');if(notice&&notice.scrollIntoView)notice.scrollIntoView({block:'nearest',behavior:'smooth'});if(document.addEventListener){if(n===10)showDialog('You’re halfway there!','<p>Sepuluh kata telah Anda temukan. Ternyata masih ada sepuluh kata lainnya yang menunggu untuk ditemukan.</p>','Lanjutkan Misi',null);else showDialog('The Final Three','<p>Kenali makna tiga kata yang belum ditemukan.</p>'+state.finalThree.map((w,i)=>`<p><b>${i+1}.</b> ${esc(DATA.words[w])}</p>`).join(''),'Lanjutkan Misi',null)}}toast(n===10?'You’re halfway there! Masih ada 10 kata.':n===17?'The Final Three · Definisi sudah tersedia.':n===20?'Discovery complete!':w+' ditemukan!')}
function wireBoard(){let board=$('#board');function hit(e){let a=board.getBoundingClientRect();let r=Math.floor((e.clientY-a.top)/a.height*16),c=Math.floor((e.clientX-a.left)/a.width*16);return r<0||c<0||r>15||c>15?null:idx(r,c)}function snap(a,b){if(a==null||b==null)return a;let r=Math.floor(a/16),c=a%16,dr=Math.floor(b/16)-r,dc=b%16-c;if(Math.abs(dr)>2*Math.abs(dc))dc=0;else if(Math.abs(dc)>2*Math.abs(dr))dr=0;else{let n=Math.min(Math.abs(dr),Math.abs(dc));dr=Math.sign(dr)*n;dc=Math.sign(dc)*n}return idx(r+dr,c+dc)}
board.onpointerdown=e=>{if(e.button!==0||drag)return;e.preventDefault();let n=hit(e);if(n==null)return;drag={id:e.pointerId,a:n,b:n,prior:selection,x:e.clientX,y:e.clientY,moved:false};board.setPointerCapture(e.pointerId);paint([n])};board.onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;let n=hit(e);if(n==null)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>8)drag.moved=true;if(drag.moved){drag.b=snap(drag.a,n);paint(path(drag.a,drag.b))}};board.onpointerup=e=>{if(!drag||drag.id!==e.pointerId)return;let d=drag;drag=null;if(d.moved&&d.a!==d.b)return choose(d.a,d.b);let n=hit(e);if(n==null){selection=null;paint();return}if(d.prior!=null&&d.prior!==n)return choose(d.prior,n);selection=d.prior===n?null:n;paint()};board.onpointercancel=()=>{drag=null;selection=null;paint()};board.onkeydown=e=>{let el=e.target.closest('[data-cell]');if(!el)return;let n=+el.dataset.cell,r=Math.floor(n/16),c=n%16;let moves={ArrowUp:[-1,0],ArrowDown:[1,0],ArrowLeft:[0,-1],ArrowRight:[0,1]};if(moves[e.key]){e.preventDefault();let [dr,dc]=moves[e.key],a=r+dr,b=c+dc;if(a>=0&&a<16&&b>=0&&b<16){el.tabIndex=-1;let next=board.querySelector(`[data-cell="${idx(a,b)}"]`);next.tabIndex=0;next.focus()}}else if(['Enter',' '].includes(e.key)){e.preventDefault();if(selection!=null&&selection!==n)choose(selection,n);else{selection=n;paint()}}else if(e.key==='Escape'){selection=null;paint()}}}
let dialogAction=null,dialogCancel=null,dialogOpen=false;
function closeDialog(){let d=$('#appDialog');if(d){d.hidden=true;d.innerHTML='';d.classList?.remove('bottom-sheet')}dialogOpen=false;dialogAction=null;dialogCancel=null}
function showDialog(title,body,primary,secondary,onPrimary=()=>{},onSecondary=()=>{}){closeDialog();let d=$('#appDialog');dialogOpen=true;dialogAction=onPrimary;dialogCancel=onSecondary;d.hidden=false;d.innerHTML=`<div class="dialog-card" role="dialog" aria-modal="true" aria-labelledby="dialogTitle"><h2 id="dialogTitle">${title}</h2><div class="dialog-body">${body}</div><button id="dialogPrimary" class="btn gold full">${primary}</button>${secondary?`<button id="dialogSecondary" class="btn secondary full">${secondary}</button>`:''}</div>`;$('#dialogPrimary').onclick=()=>{let f=dialogAction;closeDialog();f?.()};if(secondary)$('#dialogSecondary').onclick=()=>{let f=dialogCancel;closeDialog();f?.()};$('#dialogPrimary').focus()}
function isOngoing(r){return r==='word'&&state.wordStart&&!state.wordEnd?'word':r==='thinking'&&thinkingScreen==='questions'&&state.thinkingStart&&!state.assessment?'thinking':null}
function confirmLeave(kind,proceed){save();let copy=storageError?'Progres belum dapat disimpan di perangkat ini. Keluar dapat menyebabkan data hilang.':'Progres tersimpan di perangkat ini dan dapat dilanjutkan kembali.';showDialog(kind==='word'?'Pause Your Discovery?':'Pause Your Assessment?',`<p>${kind==='word'?'Masih ada bagian dari misi yang belum Anda selesaikan.':'Anda belum menyelesaikan inventori.'} ${copy}</p>`,kind==='word'?'Lanjutkan Misi':'Lanjutkan Assessment',kind==='word'?'Tinggalkan Tantangan':'Keluar dari Assessment',()=>{},proceed)}
const allowedRoutes=['home','magazine','thinking','word','profile'];
function commitRoute(r,replace=false){if(!allowedRoutes.includes(r))r='home';closeDialog();if(r!==activeRoute){readerScale=1;readerControls=true;readerBusy=false}if(location.hash!=='#'+r){if(replace)history.replaceState(null,'','#'+r);else history.pushState(null,'','#'+r)}activeRoute=r;render();scrollTo(0,0);if(r!=='magazine'&&app.animate&&!matchMedia('(prefers-reduced-motion: reduce)').matches)app.animate([{opacity:.65,transform:`translateX(${r==='home'?-10:10}px)`},{opacity:1,transform:'translateX(0)'}],{duration:180,easing:'ease-out'})}
function requestRoute(r){if(r===activeRoute)return;if(welcomePending||!state.person||closed())return;let k=isOngoing(activeRoute);if(k)return confirmLeave(k,()=>commitRoute(r));commitRoute(r)}
function handleHistory(){let target=route();if(target===activeRoute)return;if(welcomePending||!state.person){history.replaceState(null,'','#home');return}let k=isOngoing(activeRoute);if(k&&!closed()){history.pushState(null,'','#'+activeRoute);confirmLeave(k,()=>commitRoute(target,true));return}commitRoute(target,true)}
function welcomeBack(){app.innerHTML=`<section class="welcome-back narrow"><p class="eyebrow">TACO × MOTU CONSULTING</p><h1>Manunggal.</h1><p class="tag">Different Minds, Shared Purpose.</p><div class="gate-icon">${icon('user')}</div><p class="eyebrow">WELCOME BACK</p><h2>Selamat datang kembali.</h2><h3>${name()}</h3><p class="team-chip">TIM ${String(state.person.team).padStart(2,'0')}</p><button id="resumeSession" class="btn gold full">Lanjutkan Perjalanan →</button><button id="switchSession" class="btn secondary full">Bukan Anda? Ganti Peserta</button></section>`;$('#resumeSession').onclick=()=>{welcomePending=false;commitRoute('home',true)};$('#switchSession').onclick=logoutPrompt}
function logout(){const pending=state.queue.slice();state={...fresh(),queue:pending};welcomePending=false;readerScale=1;thinkingScreen='intro';save();commitRoute('home',true);scheduleSync()}
function logoutPrompt(){save();showDialog('Ganti Peserta?',`<p>Sesi ini akan diakhiri. Progres di perangkat untuk peserta ini akan direset. Data yang sudah dikirim tetap tersimpan di MOTU. ${state.queue.length?'Data yang belum dikirim akan tetap berada dalam antrean sinkronisasi terpisah.':''}${storageError?' Penyimpanan perangkat bermasalah; jangan keluar sebelum data berhasil disinkronkan.':''}</p>`,'Tetap di sini','Keluar / Ganti Peserta',()=>{},()=>{if(storageError)return toast('Penyimpanan perangkat bermasalah. Hubungi fasilitator.');logout()})}
function appearanceMarkup(){return `<div class="settings-section"><h3>Preferensi Tampilan</h3><p class="small">Pilih tema yang nyaman untuk Anda. Halaman majalah tetap menggunakan warna asli.</p><fieldset class="pref-field"><legend>Tema</legend><div class="pref-options" role="group" aria-label="Tema tampilan">${[['dark','☾','Dark'],['light','☀','Light'],['system','◐','System']].map(([v,i,l])=>`<button type="button" class="pref-choice" data-theme-choice="${v}" aria-pressed="${prefs.theme===v}"><span aria-hidden="true">${i}</span>${l}</button>`).join('')}</div></fieldset><fieldset class="pref-field"><legend>Ukuran teks</legend><div class="pref-options text-options">${[['normal','Normal'],['large','Lebih besar']].map(([v,l])=>`<button type="button" class="pref-choice" data-text-choice="${v}" aria-pressed="${prefs.text===v}">${l}</button>`).join('')}</div></fieldset><p class="small">Preferensi tersimpan pada browser ini.</p></div>`}
function wireAppearance(root=document){root.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{setPrefs({theme:b.dataset.themeChoice});root.querySelectorAll('[data-theme-choice]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.themeChoice===prefs.theme)))});root.querySelectorAll('[data-text-choice]').forEach(b=>b.onclick=()=>{setPrefs({text:b.dataset.textChoice});root.querySelectorAll('[data-text-choice]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.textChoice===prefs.text)))})}
function openAppearance(){showDialog('Pengaturan Tampilan',appearanceMarkup(),'Selesai',null);wireAppearance($('#appDialog'))}
function usageHelp(){showDialog('Bantuan Penggunaan','<p><b>Experience Guide:</b> ketuk sisi kanan atau kiri, geser halaman, atau pilih Daftar Isi. Cubit layar untuk memperbesar.</p><p><b>Thinking Style:</b> pilih tepat dua karakteristik pada tiap kelompok pernyataan.</p><p><b>Word Hunt:</b> gunakan kode akses dari fasilitator. Geser jari sepanjang kata atau ketuk huruf awal dan akhir.</p><p><b>Progres:</b> tersimpan di browser yang sama. Gunakan Keluar / Ganti Peserta hanya untuk mengakhiri sesi pribadi.</p>','Mengerti',null)}
function participantProfile(){app.innerHTML=nav('Participant Profile')+`<section class="participant-card narrow"><div class="gate-icon">${icon('user')}</div><h2>${name()}</h2><p class="team-chip">TIM ${String(state.person.team).padStart(2,'0')}</p>${appearanceMarkup()}<form id="editIdentity"><h3>Edit Identitas</h3><label class="field">Nama lengkap<input required maxlength="100" name="name" value="${name()}"></label><label class="field">Nomor tim<select name="team">${Array.from({length:30},(_,i)=>`<option value="${i+1}" ${state.person.team===i+1?'selected':''}>Tim ${String(i+1).padStart(2,'0')}</option>`).join('')}</select></label><button class="btn gold full">Simpan Identitas</button></form><div class="profile-section"><button id="syncNow" class="btn secondary full">Sinkronisasi Data</button><p id="profileSync" class="small" aria-live="polite"></p><button id="usageHelp" class="btn secondary full">Bantuan Penggunaan</button><button id="logout" class="btn secondary full danger-text">Keluar / Ganti Peserta</button></div></section>`;$('#editIdentity').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),n=f.get('name').trim();if(!n||/[\x00-\x1f\x7f]/.test(n))return toast('Nama belum valid.');state.person={...state.person,name:n,team:Number(f.get('team'))};save();enqueue('register',{});participantProfile();toast('Identitas diperbarui. Progres tetap tersimpan.')};$('#syncNow').onclick=()=>{if(demo)return toast('Mode uji: data lokal saja.');retryAt=0;closedAcked=false;clock();scheduleSync();toast('Memeriksa sinkronisasi…')};$('#logout').onclick=logoutPrompt;$('#usageHelp').onclick=usageHelp;wireAppearance(app);status()}
// Refresh state and resume delivery, never claim delivery from opaque POST alone.
document.addEventListener('click',e=>{let a=e.target.closest('a[href^="#"]');if(!a)return;let r=a.getAttribute('href').slice(1);if(!allowedRoutes.includes(r))return;e.preventDefault();if(dialogOpen)closeDialog();requestRoute(r)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dialogOpen){closeDialog();return}if(route()==='magazine'&&!dialogOpen&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();$(e.key==='ArrowLeft'?'#prev':'#next')?.click()}});


window.addEventListener('hashchange',handleHistory);window.addEventListener('online',()=>{retryAt=0;closedAcked=false;clock();scheduleSync()});window.addEventListener('visibilitychange',()=>{if(!document.hidden){clock();scheduleSync();if(closed())render()}});window.addEventListener('resize',()=>{if(route()==='magazine'&&state.person&&!closed()&&!readerBusy&&!welcomePending)magazine()});setInterval(()=>{if(closed()&&!app.querySelector('.closed'))render();scheduleSync()},4000);setInterval(clock,120000);
$('#appearance').onclick=openAppearance;const systemTheme=matchMedia('(prefers-color-scheme: dark)');const systemChange=()=>{if(prefs.theme==='system')applyPrefs()};if(systemTheme.addEventListener)systemTheme.addEventListener('change',systemChange);else systemTheme.addListener?.(systemChange);
// New browser load always starts at identity confirmation / home.
if(location.hash!=='#home')history.replaceState(null,'','#home');activeRoute='home';save();render();clock();scheduleSync();
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
